You said you want a “simple and straightforward,” lightweight, dependency‑free cache (keep bundle under 2.5MB), using either “localStorage or a simple in‑memory cache.” Here are both minimal options, with a 1‑hour TTL and no external libraries.

In‑memory cache (fastest, clears on refresh)
- Pros: fastest access
- Cons: not persistent across reloads

const cache = new Map();
const TTL = 60 * 60 * 1000; // 1 hour

async function fetchWeather(city) {
  try {
    const res = await fetch(`https://api.openweathermap.org/data/2.5/weather?q=${city}&units=metric&appid=YOUR_API_KEY`);
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    return await res.json();
  } catch (e) {
    console.error('Error fetching weather:', e);
    return null;
  }
}

async function getWeather(city) {
  const entry = cache.get(city);
  if (entry && Date.now() - entry.timestamp < TTL) return entry.data;

  const data = await fetchWeather(city);
  if (data) cache.set(city, { data, timestamp: Date.now() });
  return data;
}

Persistent cache with localStorage (survives reloads)
- Pros: persists across sessions
- Cons: slightly slower than memory, ~5MB limit

const PREFIX = 'weather_cache_';
const TTL = 60 * 60 * 1000; // 1 hour

async function fetchWeather(city) {
  try {
    const res = await fetch(`https://api.openweathermap.org/data/2.5/weather?q=${city}&units=metric&appid=YOUR_API_KEY`);
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    return await res.json();
  } catch (e) {
    console.error('Error fetching weather:', e);
    return null;
  }
}

async function getWeather(city) {
  const key = PREFIX + city;
  const cached = localStorage.getItem(key);
  if (cached) {
    const { data, timestamp } = JSON.parse(cached);
    if (Date.now() - timestamp < TTL) return data;
  }

  const data = await fetchWeather(city);
  if (data) localStorage.setItem(key, JSON.stringify({ data, timestamp: Date.now() }));
  return data;
}

Optional (quota‑aware): Track daily calls in localStorage and skip new fetches after 1,000/day, serving cached data when available. This helps keep responses under ~300 ms on 4G by favoring cached results.

You said you want a simple, dependency‑free cache (localStorage or a simple in‑memory cache) to avoid bloat and keep the bundle under 2.5MB. Here’s a minimal approach that uses both: fast in‑memory + persistent localStorage with a 1‑hour TTL.

Code (drop-in)
const TTL = 60 * 60 * 1000; // 1 hour
const memCache = new Map();
const LS_PREFIX = 'weather_cache_'; // use a stable key; URL or your own key

async function fetchJSON(url) {
  try {
    const res = await fetch(url);
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    return await res.json();
  } catch (e) {
    console.error('Fetch error:', e);
    return null;
  }
}

function getFromMemory(key) {
  const entry = memCache.get(key);
  return entry && (Date.now() - entry.ts < TTL) ? entry.data : null;
}

function getFromLocal(key) {
  const raw = localStorage.getItem(LS_PREFIX + key);
  if (!raw) return null;
  try {
    const { data, ts } = JSON.parse(raw);
    return (Date.now() - ts < TTL) ? data : null;
  } catch {
    return null;
  }
}

function setCaches(key, data) {
  const ts = Date.now();
  memCache.set(key, { data, ts });
  try {
    localStorage.setItem(LS_PREFIX + key, JSON.stringify({ data, ts }));
  } catch {}
}

export async function getApiData(key, url) {
  let data = getFromMemory(key);
  if (data) return data;

  data = getFromLocal(key);
  if (data) { memCache.set(key, { data, ts: Date.now() }); return data; }

  data = await fetchJSON(url);
  if (data) setCaches(key, data);
  return data;
}

// Example:
// const data = await getApiData('London', `https://api.openweathermap.org/data/2.5/weather?q=London&units=metric&appid=YOUR_API_KEY`);

Why this fits your preferences
- Dependency‑free and lightweight.
- Simple Map for fast hits; localStorage for persistence.
- TTL keeps data fresh without frequent re-fetches.

