You said you want it simple and straightforward, prefer lightweight, dependency‑free solutions, and are fine with either a simple in‑memory cache or localStorage (keeping the bundle under 2.5MB). Here’s a minimal, no‑dependency cache that uses both: fast in‑memory plus persistent localStorage with a 1‑hour TTL.

const CACHE_TTL = 60 * 60 * 1000; // 1 hour
const LS_PREFIX = 'weather_cache_';
const memCache = new Map();

async function fetchWeather(city) {
  try {
    const res = await fetch(`https://api.openweathermap.org/data/2.5/weather?q=${encodeURIComponent(city)}&units=metric&appid=YOUR_API_KEY`);
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    return await res.json();
  } catch (e) {
    console.error('Error fetching weather:', e);
    return null;
  }
}

function readLocal(city) {
  const raw = localStorage.getItem(LS_PREFIX + city);
  if (!raw) return null;
  try {
    const { data, timestamp } = JSON.parse(raw);
    if (Date.now() - timestamp < CACHE_TTL) return data;
  } catch {}
  return null;
}

function writeLocal(city, data) {
  try {
    localStorage.setItem(LS_PREFIX + city, JSON.stringify({ data, timestamp: Date.now() }));
  } catch {}
}

export async function getWeather(city) {
  const key = city.trim();

  const mem = memCache.get(key);
  if (mem && Date.now() - mem.timestamp < CACHE_TTL) return mem.data;

  const ls = readLocal(key);
  if (ls) {
    memCache.set(key, { data: ls, timestamp: Date.now() });
    return ls;
  }

  const data = await fetchWeather(key);
  if (data) {
    const entry = { data, timestamp: Date.now() };
    memCache.set(key, entry);
    writeLocal(key, data);
  }
  return data;
}

// Example
getWeather('London').then(console.log);

Notes:
- localStorage persists across sessions but has size limits; memory is fastest for repeat hits.
- Adjust CACHE_TTL (e.g., 30–60 min) to balance freshness with the 1,000/day quota and keep responses under ~300 ms on 4G.
